import time
class Session:
    def __init__(self):
        self.s = {}
    def put(self, k, v, ttl):
        self.s[k] = (v, time.time() + ttl)
    def get(self, k):
        if k not in self.s: return None
        v, e = self.s[k]
        if e is not None and time.time() >= e: return None
        return v

